import os,json,hashlib,subprocess,time,traceback
from pathlib import Path
from datetime import datetime,timezone
root=Path("/u/scratch/r/rushil/AI_Assisted_SIDIS/polarized_SIDIS_20260917T063521Z")
os.environ.update(LC_ALL='C',LANG='C')
pins=json.loads("{\"common/s08_check_Hgg_reference_map.wls\":\"4261bb809315d37609ba424f0e59969730cf68374273b5a145e7fe6257180e15\",\"Hgg/s08_reference_map_comparison_result/s08_result.wl\":\"e1f742f05e11adbd78f9741c8a405f0d2a2ff53f7a9d146e92951ba90621cd21\",\"Hgg/s08_reference_map_comparison_result/s08_checks.json\":\"7041a11f84a5ce6844161c152f948044782dd99714fa4f984fbc0a0b1918d105\",\"Hgg/s08_reference_map_comparison_result/s08_execution.json\":\"9a359e3cd4e9c07b91cb73ad631236a93ff1fa3e12deb9a7176ad5a895d4b675\",\"common/s08_map_Hgg_external_factors.wls\":\"f56a17a46371995ea64efcecc35eae81f55162f77b121b0119a19c31a90a6c87\",\"common/s08_result/reference/s08_map_Hgg_external_factors_before_reference_equality.wls\":\"8f2270347a3662a6544fd557fe632abcafca8c9761ffa8b0310d99c4e74adf63\"}")
basepath=root/'.cluster/s08_Hgg_eight_workers_20260924_part2_job.json'
basehash='84f6fb8c12eefcafecdd5eabf4fd3276034792d8ecc537e57d2ca6d5a504aca8'
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def event(name,**kw):
    row={'event':name,'utc':datetime.now(timezone.utc).isoformat()};row.update(kw);print(json.dumps(row),flush=True)
def checkpoint_state():
    paths=[root/'cache/s08_targets/Hgg/16b0520991009b919853f87279b692e4495f4c1d831cc2c4371c4bca03e7a607',
      root/'cache/s08_Hgg_grouped/244be3fbf4bd6c97320bdf9194b8d1744e45b97597929aba9717bf70927353ec',
      root/'cache/s08_Hgg_grouped/244be3fbf4bd6c97320bdf9194b8d1744e45b97597929aba9717bf70927353ec_numeric_phase']
    rows=[]
    for d in paths:
        values=[(str(p.relative_to(d)),p.stat().st_size,p.stat().st_mtime_ns) for p in d.rglob('*.wl') if p.is_file()]
        rows.append({'files':len(values),'bytes':sum(v[1] for v in values),'identity':hashlib.sha256(repr(sorted(values)).encode()).hexdigest()})
    return rows
def run():
    if digest(basepath)!=basehash: raise RuntimeError('base configuration changed')
    base=json.loads(basepath.read_text())
    base['reviewed_sha256'].update(pins)
    for rel,h in base['reviewed_sha256'].items():
        if digest(root/rel)!=h: raise RuntimeError('reviewed input changed: '+rel)
    receiptpath=root/base['execution_result']
    for attempt in range(1,9):
        tag='s08_Hgg_reference_equal_20260924_part'+str(attempt)
        if receiptpath.exists():
            old=json.loads(receiptpath.read_text())
            if old.get('passed'):
                for rel,h in old['result_sha256'].items():
                    if digest(root/rel)!=h: raise RuntimeError('accepted output changed '+rel)
                event('MAPPING_ACCEPTED',job_id=old['job_id'],receipt=base['execution_result']);return
            archive=root/('.cluster/s08_result/'+tag+'_prior_'+str(old['job_id'])+'_execution.json')
            if archive.exists(): raise RuntimeError('prior receipt archive exists')
            receiptpath.replace(archive)
        j=json.loads(json.dumps(base))
        j['log']='cache/'+tag+'.log';j['heartbeat']='cache/'+tag+'_heartbeat.json'
        for key in ['MATHEMATICA_USERBASE','WOLFRAM_USERBASE']: j['environment'][key]='{root}/cache/wolfram_'+tag
        cfg='.cluster/'+tag+'_job.json';cp=root/cfg
        before=checkpoint_state()
        subpath=root/('.cluster/s08_result/'+tag+'_submission.json')
        if cp.exists():
            if not subpath.exists(): raise RuntimeError('configuration lacks submission receipt')
            sub=json.loads(subpath.read_text())
            if sub['configuration_sha256']!=digest(cp) or json.loads(cp.read_text())!=j: raise RuntimeError('adopted configuration changed')
            jid=sub['job_id']
        else:
            cp.write_text(json.dumps(j,indent=2,sort_keys=True)+'\n')
            args=['qsub','-terse','-N','pSIDIS_'+tag,'-S','/bin/bash','-pe','shared','8','-l','h_rt=02:00:00,h_data=10G','-wd',str(root),'-j','y','-o',str(root/('cache/'+tag+'_scheduler.log'))]
            script='#!/bin/bash\nset -eu\nexport LC_ALL=C LANG=C\nexec python3 '+str(root/'.cluster/s02_execute.py')+' --root '+str(root)+' --job '+cfg+'\n'
            p=subprocess.run(args,input=script,stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True)
            if p.returncode: raise RuntimeError(p.stderr)
            jid=p.stdout.strip().split('.')[0]
            sub={'job_id':jid,'config':cfg,'configuration_sha256':digest(cp),'qsub':args,'script':script,'utc':datetime.now(timezone.utc).isoformat()}
            subpath.write_text(json.dumps(sub,indent=2)+'\n')
        event('SUBMITTED',**sub,checkpoint_state=before)
        last=None;missing=0;lastchange=time.monotonic()
        while not receiptpath.exists():
            p=subprocess.run(['qstat','-j',jid],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=30)
            lp=root/j['log'];size=lp.stat().st_size if lp.exists() else 0
            beat=root/j['heartbeat'];heartbeat=json.loads(beat.read_text()) if beat.exists() else {}
            state=(p.returncode,size)
            if state!=last:
                last=state;lastchange=time.monotonic()
                tail='\n'.join(lp.read_text(errors='replace').splitlines()[-6:])[-4000:] if size else ''
                event('NATIVE_PROGRESS',job_id=jid,log_bytes=size,tail=tail,heartbeat=heartbeat)
            missing=missing+1 if p.returncode else 0
            if missing>=6: raise RuntimeError('job disappeared without receipt: '+jid)
            if size and time.monotonic()-lastchange>j['limits']['inactivity_seconds']+180:
                raise RuntimeError('native job stalled: '+jid)
            time.sleep(30)
        receipt=json.loads(receiptpath.read_text());after=checkpoint_state()
        lp=root/j['log'];tail='\n'.join(lp.read_text(errors='replace').splitlines()[-18:])[-7000:]
        event('STAGE_FINISHED',job_id=jid,passed=receipt.get('passed'),reason=receipt.get('reason'),exit_code=receipt.get('exit_code'),checkpoint_state=after,tail=tail)
        if receipt.get('passed'):
            for rel,h in receipt['result_sha256'].items():
                if digest(root/rel)!=h: raise RuntimeError('accepted output changed '+rel)
            event('MAPPING_ACCEPTED',job_id=jid,receipt=base['execution_result']);return
        if receipt.get('reason')!='wall_limit' or before==after:
            raise RuntimeError('mapping needs inspection: '+jid+' '+str(receipt.get('reason')))
        event('RESUME_FROM_NEW_CHECKPOINTS',job_id=jid,checkpoint_state=after)
    raise RuntimeError('checkpoint continuation limit reached')
try:
    run()
except Exception as exc:
    event('CONTROLLER_ERROR',error=str(exc));traceback.print_exc()
finally:
    event('CONTROLLER_EXIT')
